import { readFile, writeFile } from 'node:fs/promises'

const migrations = ['20260829170000_gomoku_rooms.sql', '20261001000000_online_room_snapshots.sql']
const parts = await Promise.all(migrations.map(async (name) => {
  const sql = await readFile(new URL(`../supabase/migrations/${name}`, import.meta.url), 'utf8')
  return `-- Source: ${name}\n${sql.replace(/^begin;\s*$/gmi, '').replace(/^commit;\s*$/gmi, '').trim()}`
}))
await writeFile(new URL('../supabase/setup-gomoku.sql', import.meta.url),
  '-- Generated by npm run db:prepare. Run once on a new project; do not append to an old query.\n'
  + '-- Creates two private tables, four RPC functions, RLS policies and Realtime publication entries.\n'
  + `begin;\n\n${parts.join('\n\n')}\n\ncommit;\n`, 'utf8')
console.log('Prepared supabase/setup-gomoku.sql as one atomic transaction.')
